    dueDate: '2026-10-05',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 100000, discountPercent: 0, vatRate: 0 }],
  };
  const fee = lateFee(invoice, '2026-10-06');
  // 100000 * 0.0004 * 1 = 40 cents
  assert.equal(fee, 40);
});

test('lateFee handles invoice due in past year', () => {
  const invoice = {
    dueDate: '2025-12-31',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const fee = lateFee(invoice, '2026-01-10');
  // 10 days overdue
  // 1000 * 0.0004 * 10 = 4 cents
  assert.equal(fee, 4);
});

test('lateFee returns 0 for draft invoice with no dueDate', () => {
  const invoice = {
    dueDate: '2026-10-15',
    status: 'draft',
    lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const fee = lateFee(invoice, '2026-10-20');
  // Draft status shouldn't matter, only dueDate comparison
  assert.equal(fee, 0);
});

test('lateFee handles rounding correctly', () => {
  const invoice = {
    dueDate: '2026-10-13',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 3, discountPercent: 0, vatRate: 0 }],
  };
  const fee = lateFee(invoice, '2026-10-15');
  // 3 * 0.0004 * 2 = 0.0024 cents, rounds to 0
  assert.equal(fee, 0);
});

test('lateFee result is always non-negative', () => {
  const invoice = {
    dueDate: '2026-10-15',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const fee = lateFee(invoice, '2026-10-14');
  assert.ok(fee >= 0);
});

